mapper.insert:

    /* UserDao.insertUser */
    select coalesce(max(u.uid), -1) + 1 from users u

/* UserDao.insertUser */
insert into users(uid, name, email, created_at)
values (#{uid}, #{name}, #{email}, #{createdAt} )

mapper.update:
/* UserDao.updateUser */
update users u set u.name = #{name}
, u.email = #{email}
, u.updated_at = #{updatedAt}
where u.uid = #{uid}
and u.deleted_at is null

/* UserDao.deleteUser */
update users u set u.deleted_at = now()
where u.uid = #{uid}
and u.deleted_at is null
